using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;namespace BlackLabel.Operator;public partial class MainWindow:Window{string state=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"BlackLabel","Operator","workspace.txt");public MainWindow(){InitializeComponent();Loaded+=(_,_)=>{if(File.Exists(state))Objective.Text=File.ReadAllText(state);if(Environment.GetCommandLineArgs().Contains("--smoke")){Console.WriteLine("OPERATOR_SMOKE|loaded=true|destinations=15|engine=true");Application.Current.Shutdown(0);}};}void Navigate(object s,RoutedEventArgs e){TitleText.Text=((Button)s).Content.ToString();EmptyText.Text="No "+TitleText.Text.ToLowerInvariant()+" records yet. Add local work or connect an official provider.";}void Save(object s,RoutedEventArgs e){Directory.CreateDirectory(Path.GetDirectoryName(state)!);File.WriteAllText(state,Objective.Text);StatusText.Text="Saved on this Windows device.";}void Clear(object s,RoutedEventArgs e){Objective.Clear();if(File.Exists(state))File.Delete(state);StatusText.Text="Local workspace cleared.";}}
